from rdkit import Chem
from rdkit.Chem import AllChem,rdMolDescriptors
from rdkit.Geometry import Point3D
rw=Chem.RWMol(); coords={}; names={}
def at(n,e,p):
 i=rw.AddAtom(Chem.Atom(e)); names[n]=i; coords[i]=p; return i
def bond(a,b,o=1,d=None):
 i=names[a];j=names[b]; typ={1:Chem.BondType.SINGLE,2:Chem.BondType.DOUBLE,'ar':Chem.BondType.AROMATIC}[o]; rw.AddBond(i,j,typ);bo=rw.GetBondBetweenAtoms(i,j)
 if o=='ar': rw.GetAtomWithIdx(i).SetIsAromatic(True);rw.GetAtomWithIdx(j).SetIsAromatic(True);bo.SetIsAromatic(True)
 if d: bo.SetBondDir(d)
# indole
a=[('A','C',(282,119)),('B','C',(351,21)),('C','C',(471,33)),('D','C',(521,144)),('E','C',(451,239)),('F','C',(329,228)),('X','C',(635,180)),('Y','C',(635,299)),('NH','N',(520,337))]
for n,e,p in a: at(n,e,p)
for u,v in [('A','B'),('B','C'),('C','D'),('D','E'),('E','F'),('F','A'),('D','X'),('X','Y'),('Y','NH'),('NH','E')]:bond(u,v,'ar')
rw.GetAtomWithIdx(names['NH']).SetNumExplicitHs(1);rw.GetAtomWithIdx(names['NH']).SetNoImplicit(True)
at('Oind','O',(205,110));at('Mind','C',(145,105));bond('A','Oind');bond('Oind','Mind')
# indole-fused 6-ring
for n,e,p in [('U','C',(739,119)),('V','C',(843,180)),('Nt','N',(843,304)),('Q','C',(739,358)),('C1','C',(946,358)),('C2','C',(946,480)),('S','C',(843,539)),('R','C',(739,480)),('C3','C',(1051,539)),('C4','C',(1051,658)),('C5','C',(947,718)),('C6','C',(843,658))]:at(n,e,p)
for u,v in [('X','U'),('U','V'),('V','Nt'),('Nt','Q'),('Q','Y'),('Nt','C1'),('C1','C2'),('C2','S'),('S','R'),('R','Q'),('C2','C3'),('C3','C4'),('C4','C5'),('C5','C6'),('C6','S')]:bond(u,v)
# wedge hydrogens from centers; dash as in drawing
for n,e,p,d in [('HQ','Q',(675,392),Chem.BondDir.BEGINWEDGE),('HC2','C2',(1010,443),Chem.BondDir.BEGINDASH),('HS','S',(775,584),Chem.BondDir.BEGINDASH)]:at(n,'H',p);bond(e,n,1,d)
# methyl ester substituent on C6
for n,e,p in [('CE','C',(739,718)),('OEcarbonyl','O',(739,655)),('OEester','O',(675,749)),('ME','C',(616,777))]:at(n,e,p)
bond('C6','CE',1,Chem.BondDir.BEGINWEDGE);bond('CE','OEcarbonyl',2);bond('CE','OEester');bond('OEester','ME')
# ring methoxy, dashed
at('O5','O',(947,800));at('M5','C',(947,857));bond('C5','O5',1,Chem.BondDir.BEGINDASH);bond('O5','M5')
# benzoate oxygen wedge from C4
for n,e,p in [('Oacyl','O',(1120,700)),('Cbz','C',(1258,658)),('Obz','O',(1258,588))]:at(n,e,p)
bond('C4','Oacyl',1,Chem.BondDir.BEGINWEDGE);bond('Oacyl','Cbz');bond('Cbz','Obz',2)
# aryl trimethoxybenzoyl
for n,p in [('P0',(1360,718)),('P1',(1465,658)),('P2',(1568,718)),('P3',(1568,837)),('P4',(1465,899)),('P5',(1360,837))]:at(n,'C',p)
for u,v in [('P0','P1'),('P1','P2'),('P2','P3'),('P3','P4'),('P4','P5'),('P5','P0')]:bond(u,v,'ar')
bond('Cbz','P0')
for ring,oxy,meth,p1,p2 in [('P2','Op2','Mp2',(1640,680),(1695,650)),('P3','Op3','Mp3',(1635,875),(1693,906)),('P4','Op4','Mp4',(1465,970),(1465,1035))]:
 at(oxy,'O',p1);at(meth,'C',p2);bond(ring,oxy);bond(oxy,meth)
m=rw.GetMol();Chem.SanitizeMol(m)
conf=Chem.Conformer(m.GetNumAtoms())
for i,(x,y) in coords.items():conf.SetAtomPosition(i,Point3D(x,-y,0))
m.AddConformer(conf)
Chem.AssignChiralTypesFromBondDirs(m,confId=0,replaceExistingTags=True);Chem.AssignStereochemistry(m,cleanIt=True,force=True)
print('before H',rdMolDescriptors.CalcMolFormula(m),Chem.MolToSmiles(m))
for n in ['Q','C2','S','C4','C5','C6']:
 a=m.GetAtomWithIdx(names[n]);print('pre',n,a.GetChiralTag(),a.GetProp('_CIPCode') if a.HasProp('_CIPCode') else '-')
