p=AllChem.ETKDGv3();p.randomSeed=287;p.useRandomCoords=False
ret=AllChem.EmbedMolecule(m,p);print('embed',ret)
# capture assigned tags / CIP preopt
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
for n in ['Q','C2','S','C4','C5','C6']:
 a=m.GetAtomWithIdx(names[n]);print('embedded tag',n,a.GetChiralTag(),a.GetProp('_CIPCode') if a.HasProp('_CIPCode') else '-')
Chem.AssignStereochemistryFrom3D(m)
for n in ['Q','C2','S','C4','C5','C6']:
 a=m.GetAtomWithIdx(names[n]);print('3d preopt',n,a.GetChiralTag(),a.GetProp('_CIPCode') if a.HasProp('_CIPCode') else '-')
AllChem.MMFFOptimizeMolecule(m,maxIters=1000)
Chem.AssignStereochemistryFrom3D(m)
for n in ['Q','C2','S','C4','C5','C6']:
 a=m.GetAtomWithIdx(names[n]);print('3d postopt',n,a.GetChiralTag(),a.GetProp('_CIPCode') if a.HasProp('_CIPCode') else '-')
with open('/root/no','w') as f: pass
conf=m.GetConformer()
with open('answer.xyz','w') as f:
 f.write(f'{m.GetNumAtoms()}\nReserpine, geometry generated from drawing\n')
 for a in m.GetAtoms():
  p=conf.GetAtomPosition(a.GetIdx()); f.write(f'{a.GetSymbol():2s} {p.x: .6f} {p.y: .6f} {p.z: .6f}\n')
print('final',rdMolDescriptors.CalcMolFormula(m),m.GetNumAtoms())
